mapper.sql:
WHERE pi.deleted = FALSE
  AND pi.canceled = FALSE
  AND o.status = 10
  AND pi.delivery_status = 10
  AND pi.warehouse_id IS NOT NULL

  AND EXISTS (
    SELECT 1
    FROM repo_supplier_publication_sku sps
    WHERE sps.deleted = FALSE
      AND sps.status = 0
      AND sps.supplier_id = #{reqVO.supplierId}
      AND sps.sku_id = pi.sku_id
  )


  AND pi.warehouse_id = #{reqVO.warehouseId}


  AND pi.window_id = #{reqVO.windowId}


  AND pi.offer_id = #{reqVO.offerId}


  AND pi.offer_sku_id = #{reqVO.offerSkuId}


  AND pi.sku_id = #{reqVO.skuId}


  AND pi.issue_no = #{reqVO.issueNo}


  AND (
    pi.product_name_snapshot LIKE CONCAT('%', #{reqVO.keyword}, '%')
    OR sku.name LIKE CONCAT('%', #{reqVO.keyword}, '%')
    OR sku_ext.isbn LIKE CONCAT('%', #{reqVO.keyword}, '%')
    OR pi.issue_name LIKE CONCAT('%', #{reqVO.keyword}, '%')
  )

mapper.select:

WHERE demand.warehouseId = #{warehouseId}
  AND demand.windowId = #{windowId}
  AND demand.offerId = #{offerId}
  AND demand.offerSkuId = #{offerSkuId}
  AND demand.skuId = #{skuId}
  AND (demand.issueId = #{issueId} OR (demand.issueId IS NULL AND #{issueId} IS NULL))
  AND demand.issueNo = #{issueNo}

SELECT warehouse_id AS warehouseId,
       window_id AS windowId,
       offer_id AS offerId,
       offer_sku_id AS offerSkuId,
       sku_id AS skuId,
       issue_id AS issueId,
       issue_no AS issueNo,
       COALESCE(SUM(received_count), 0) AS receivedCount,
       COALESCE(SUM(allocated_count), 0) AS allocatedCount,
       GREATEST(COALESCE(SUM(received_count), 0) - COALESCE(SUM(allocated_count), 0), 0) AS availableCount
FROM repo_publication_receipt_item
WHERE deleted = FALSE

  AND (

      (
        warehouse_id = #{key.warehouseId}
        AND window_id = #{key.windowId}
        AND offer_id = #{key.offerId}
        AND offer_sku_id = #{key.offerSkuId}
        AND sku_id = #{key.skuId}
        AND (issue_id = #{key.issueId} OR (issue_id IS NULL AND #{key.issueId} IS NULL))
        AND issue_no = #{key.issueNo}
      )

  )

GROUP BY warehouse_id, window_id, offer_id, offer_sku_id, sku_id, issue_id, issue_no

SELECT item.*
FROM repo_publication_receipt_item item
INNER JOIN repo_publication_receipt receipt ON receipt.id = item.receipt_id AND receipt.deleted = FALSE
WHERE item.deleted = FALSE
  AND receipt.status IN (20, 30, 40, 50)
  AND item.warehouse_id = #{key.warehouseId}
  AND item.window_id = #{key.windowId}
  AND item.offer_id = #{key.offerId}
  AND item.offer_sku_id = #{key.offerSkuId}
  AND item.sku_id = #{key.skuId}
  AND (item.issue_id = #{key.issueId} OR (item.issue_id IS NULL AND #{key.issueId} IS NULL))
  AND item.issue_no = #{key.issueNo}
  AND item.received_count > item.allocated_count
ORDER BY item.id ASC
FOR UPDATE
